<script setup lang="ts">
import { shallowRef } from 'vue'
import { useControlFocus } from '@building-suit/ux'
import type { BsFinancialAccountCopy, BsFinancialAccountFilters, BsFinancialAccountForm, BsFinancialAccountsView, BsAccountClassificationForm, BsControlAdjustmentForm } from '../types/financialAccountsPresentation'
import type { BsAccountActivityForm } from '../types/accountActivityPresentation'
defineProps<{ copy: BsFinancialAccountCopy; view: BsFinancialAccountsView }>()
const filters = defineModel<BsFinancialAccountFilters>('filters', { required: true })
const editor = defineModel<BsFinancialAccountForm>('editor', { required: true })
const classification = defineModel<BsAccountClassificationForm>('classification', { required: true })
const adjustment = defineModel<BsControlAdjustmentForm>('adjustment', { required: true })
const activity = defineModel<BsAccountActivityForm>('activity', { required: true })
const emit = defineEmits<{ create: [parent?: string]; edit: [id: string]; archive: [id: string]; classify: [id: string]; openActivity: [id: string]; clearSearch: []; reveal: []; retry: []; toggle: [id: string]; expandAll: []; collapseAll: []; emptyAction: []; closeTemplates: []; closeEditor: []; saveEditor: []; closeClassification: []; saveClassification: []; retryClassification: []; openAdjustment: [id: string]; closeAdjustment: []; saveAdjustment: []; closeActivity: []; activityBack: []; activityApply: []; activityRetry: []; activityPage: [direction: number]; activityJournal: [id: string, entryId: string]; activityAccount: [id: string, entryId: string] }>()
const searchControl = shallowRef<unknown>(null)
const focus = useControlFocus(shallowRef<HTMLElement | null>(null), searchControl)
function field<K extends keyof BsFinancialAccountFilters>(key: K, value: BsFinancialAccountFilters[K]) { filters.value = { ...filters.value, [key]: value } }
function clearSearch() { emit('clearSearch'); focus.focus() }
function reveal() { emit('reveal'); focus.focus() }
</script>
<template>
 <BsStack :data-hydrated="view.ready" gap="lg"><BsPageHeader :title="copy.title" :subtitle="copy.subtitle" :context="view.context" :context-label="copy.context"><template #actions><BsFieldLabel><BsCheckbox :model-value="filters.archived" bare @update:model-value="field('archived', !!$event)"/>{{ copy.showArchived }}</BsFieldLabel><BsButton v-if="filters.view === 'tree' && view.canCreate" :disabled="!view.ready" variant="primary" @click="emit('create')">{{ copy.add }}</BsButton></template></BsPageHeader>
  <BsChartTemplateReview :model-value="filters.template" :view="view.templates" :code-label="copy.code" :account-label="copy.account" :role-label="copy.role" @update:model-value="field('template', $event)" @close="emit('closeTemplates')"/>
  <BsInline role="group" :aria-label="copy.view" wrap><BsButton v-for="mode in (['tree', 'table'] as const)" :key="mode" variant="chip" :aria-pressed="filters.view === mode" :disabled="!view.ready" @click="field('view', mode)">{{ mode === 'tree' ? copy.treeView : copy.tableView }}</BsButton></BsInline><BsInline v-if="filters.view === 'table'" role="tablist" :aria-label="copy.tabs" wrap><BsButton v-for="group in view.groups" :id="`account-tab-${group.value}`" :key="group.value" variant="tab" role="tab" :aria-controls="`account-panel-${group.value}`" :aria-selected="filters.tab === group.value" @click="field('tab', group.value)">{{ group.label }}</BsButton></BsInline>
  <BsInline wrap align="end"><BsBox><BsFieldLabel for="account-search">{{ copy.search }}</BsFieldLabel><BsInput id="account-search" ref="searchControl" :model-value="filters.search" type="search" :placeholder="copy.searchPlaceholder" :aria-controls="filters.view === 'tree' ? 'accounts-tree' : 'accounts-table'" :disabled="!view.ready || view.loading || view.failed" @update:model-value="field('search', String($event ?? ''))"/></BsBox><BsButton v-if="filters.search" @click="clearSearch">{{ copy.clear }}</BsButton><BsText v-if="!view.loading && !view.failed" role="status" data-testid="account-result-count" size="sm" tone="muted">{{ view.searchCount }}</BsText></BsInline><BsCard v-if="view.savedHidden && !view.loading && !view.failed" role="status" padding="md"><BsText size="sm">{{ view.savedHidden }}</BsText><BsButton @click="reveal">{{ copy.reveal }}</BsButton></BsCard>
  <BsBox v-if="view.loading" role="status" :aria-label="copy.loading"><BsVisuallyHidden>{{ copy.loading }}</BsVisuallyHidden><BsSectionSkeleton variant="table" :rows="8"/></BsBox><BsStateSurface v-else-if="view.failed" state="error" :title="copy.failed" :description="copy.failedHint" :action-label="copy.retry" @action="emit('retry')"/><BsEmptyState v-else-if="!view.hasAccounts && filters.view === 'table'" :title="copy.empty" :description="copy.emptyHint" :action-label="view.canCreate ? copy.add : undefined" @action="emit('create')"/>
  <BsCard v-else-if="filters.view === 'tree'" :aria-label="copy.treeTitle" padding="none" overflow="hidden"><BsInline wrap justify="between" padding="lg"><BsBox><BsHeading :level="2" size="h3">{{ copy.treeTitle }}</BsHeading><BsText size="sm" tone="muted">{{ view.treeHint }}</BsText></BsBox><BsInline wrap><BsButton :disabled="!view.ready || !!filters.search" size="sm" @click="emit('expandAll')">{{ copy.expandAll }}</BsButton><BsButton :disabled="!view.ready || !!filters.search" size="sm" @click="emit('collapseAll')">{{ copy.collapseAll }}</BsButton></BsInline></BsInline><BsDataTable id="accounts-tree" :value="view.treeRows" data-key="id" :label="copy.treeTitle" :columns="[{ key: 'name', header: copy.account }, { key: 'balance', header: copy.balance, align: 'end' }]"><template #cell-name="{ row }"><BsHierarchyBranch :depth="row.depth"><BsButton v-if="row.hasChildren" :aria-expanded="row.expanded" :aria-label="row.toggleLabel" :disabled="!view.ready || !!filters.search" @click="emit('toggle', row.id)"><BsIcon :name="row.expanded ? 'arrowDown' : 'arrowRight'" directional :size="16"/></BsButton><BsHierarchyLeaf v-else aria-hidden="true" as="span"/><BsBox grow><BsInline wrap align="baseline"><BsText v-if="row.code" dir="ltr" as="span" size="sm" tone="muted">{{ row.code }}</BsText><BsButton v-if="row.canActivity" variant="link" :disabled="!view.ready" align="start" @click="emit('openActivity', row.id)">{{ row.name }}</BsButton><BsText v-else as="span">{{ row.name }}</BsText><BsText v-if="row.count" as="span">{{ row.count }}</BsText><BsBadge v-if="row.archived">{{ copy.archived }}</BsBadge></BsInline><BsText v-if="row.detail" size="sm" tone="muted">{{ row.detail }}</BsText><BsDisclosure v-if="row.canEdit || row.canArchive || row.canCreateChild || row.canClassify" :aria-label="row.actionsLabel"><template #summary>{{ copy.more }}</template><BsInline wrap><BsButton v-if="row.canEdit" size="sm" @click="emit('edit', row.id)">{{ copy.edit }}</BsButton><BsButton v-if="row.canCreateChild" size="sm" @click="emit('create', row.id)">{{ copy.addChild }}</BsButton><BsButton v-if="row.canClassify" size="sm" @click="emit('classify', row.id)">{{ copy.classify }}</BsButton><BsButton v-if="row.canArchive" size="sm" @click="emit('archive', row.id)">{{ copy.archive }}</BsButton></BsInline></BsDisclosure></BsBox></BsHierarchyBranch></template><template #cell-balance="{ row }"><BsText>{{ row.balance }}</BsText><BsText v-if="row.side" size="xs" tone="muted">{{ row.side }}</BsText><BsText v-if="row.subtotal" size="xs" tone="muted">{{ row.subtotal }}</BsText><BsText v-if="row.direct" size="xs" tone="muted">{{ row.direct }}</BsText></template><template #empty><BsText tone="muted">{{ copy.noResults }}</BsText></template></BsDataTable></BsCard>
  <BsCard v-else :id="`account-panel-${filters.tab}`" role="tabpanel" :aria-labelledby="`account-tab-${filters.tab}`" padding="none" overflow="hidden"><BsInline justify="between"><BsHeading :level="2" size="body">{{ view.groupLabel }}</BsHeading><BsText>{{ view.groupTotal }}</BsText></BsInline><BsText size="xs" tone="muted">{{ view.totalHint }}</BsText><BsDataTable id="accounts-table" :first="filters.first" :sort-field="filters.sortField" :sort-order="filters.sortOrder" paginator :rows="25" :always-show-paginator="false" :value="view.rows" data-key="id" :label="view.groupLabel" :capabilities="{ insert: view.canCreate, edit: view.rows.some(row => row.canEdit), archive: view.rows.some(row => row.canArchive) }" :action-labels="{ insert: copy.add, edit: copy.edit, archive: copy.archive, actions: copy.actions }" :can-row-action="(action, row) => action === 'archive' ? row.canArchive : action === 'edit' ? row.canEdit : true" :columns="[{ key: 'code', field: 'code', header: copy.code, sortable: true }, { key: 'name', field: 'name', header: copy.account, sortable: true }, { key: 'role', field: 'role', header: copy.role }, { key: 'subledger', header: copy.subledger }, { key: 'subtype', field: 'subtype', header: copy.subtype }, { key: 'normal', field: 'normal', header: copy.normal }, { key: 'contra', field: 'contra', header: copy.contra }, { key: 'currency', field: 'currency', header: copy.currency }, { key: 'entries', field: 'entries', header: copy.entries, align: 'end' }, { key: 'balance', header: copy.balance, align: 'end' }]" @update:first="field('first', $event)" @update:sort-field="field('sortField', String($event ?? 'code'))" @update:sort-order="field('sortOrder', $event === -1 ? -1 : 1)" @create="emit('create')" @edit="emit('edit', $event.id)" @archive="emit('archive', $event.id)"><template #cell-name="{ row }"><BsButton v-if="row.canActivity" variant="link" :disabled="!view.ready" align="start" @click="emit('openActivity', row.id)">{{ row.name }}</BsButton><BsText v-else as="span">{{ row.name }}</BsText><BsStatusBadge v-if="row.archived" status="archived" :label="copy.archived" tone="neutral"/><BsStatusBadge v-else-if="row.liquid" status="liquid" :label="copy.liquid" tone="info"/></template><template #cell-subledger="{ row }"><BsText as="span">{{ row.subledger }}</BsText><BsStatusBadge v-if="row.bindingLocked" status="locked" :label="copy.bindingLocked" tone="neutral"/></template><template #cell-balance="{ row }"><BsText as="span">{{ row.balance }} {{ row.side }}</BsText></template><template #row-actions="{ row }"><BsButton v-if="row.canClassify" size="sm" @click="emit('classify', row.id)">{{ copy.classify }}</BsButton></template><template #empty><BsEmptyState :title="view.emptyTitle" :description="view.emptyHint" :action-label="view.emptyAction || undefined" @action="emit('emptyAction')"/></template><template #paginatorcontainer="{ page, pageCount, prevPageCallback, nextPageCallback }"><BsInline as="nav" :aria-label="copy.pages" wrap justify="center" padding="md"><BsButton :disabled="page === 0" size="sm" @click="prevPageCallback">{{ copy.previous }}</BsButton><BsText>{{ page + 1 }} / {{ pageCount }}</BsText><BsButton :disabled="page + 1 >= (pageCount || 1)" size="sm" @click="nextPageCallback">{{ copy.next }}</BsButton></BsInline></template></BsDataTable></BsCard>
  <BsControlReconciliationPanel v-model:form="adjustment" :date="filters.controlDate" :copy="view.controls.copy" :view="view.controls.view" :account-label="copy.account" :actions-label="copy.actions" :save-label="copy.save" :cancel-label="copy.cancel" @update:date="field('controlDate', $event)" @adjust="emit('openAdjustment', $event)" @close="emit('closeAdjustment')" @save="emit('saveAdjustment')"/>
  <BsAccountEditorDialog v-model:form="editor" :copy="copy" :view="view.editor" @close="emit('closeEditor')" @save="emit('saveEditor')"/><BsAccountClassificationDialog v-model:form="classification" :copy="view.classification.copy" :view="view.classification.view" @close="emit('closeClassification')" @save="emit('saveClassification')" @retry="emit('retryClassification')"/><BsAccountActivityDialog v-model:form="activity" :copy="view.activity.copy" :view="view.activity.view" @close="emit('closeActivity')" @back="emit('activityBack')" @apply="emit('activityApply')" @retry="emit('activityRetry')" @page="emit('activityPage', $event)" @journal="(id, entryId) => emit('activityJournal', id, entryId)" @account="(id, entryId) => emit('activityAccount', id, entryId)"/>
 </BsStack>
</template>
